/*
 * A116468  Permutation of natural numbers generated by 2-rowed array shown
 *          below.
 * https://oeis.org/A116468
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(1) = 2; for n%4 == 0 a(n) = n + 2; for n%4 == 2 a(n) = n + 1;
 *            for n%4 == 3 a(n) = n - 2; for n%4 == 1 a(n) = n - 1 (n >= 5).
 *            This implements the recurrence a(n+4k) = a(n) + 4k for k >= 1,
 *            with the given initial values
 * Range:     u8 n <= 66, u16 n <= 66, u32 n <= 66, u64 n <= 66, u128 n <= 66,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* Handle the first term separately */
    if (n == 1U) {
        return (seq_t)2;
    }

    /* For n >= 2, use the residue class modulo 4 */
    idx_t r = n & 3U;  /* n % 4 */

    if (r == 0U) {
        return (seq_t)(n + 2U);
    }
    if (r == 2U) {
        return (seq_t)(n + 1U);
    }
    if (r == 3U) {
        return (seq_t)(n - 2U);
    }
    /* r == 1U; n is at least 5 here, so n-1 is safe */
    return (seq_t)(n - 1U);
}
